import java.io.*;
import java.util.*;

public class Main {
    private static final long MOD = 998244353L;
    private static long[] factorial;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        int t = 1;
        while (t-- > 0) {
            int n = in.readInt();
            long k = in.readLong();

            factorial = new long[n + 1];
            factorial[0] = factorial[1] = 1L;
            for (int i = 2; i <= n; i++) {
                factorial[i] = (factorial[i - 1] * i) % MOD;
            }

            if (k == 0) {
                out.printLine(factorial[n]);
            } else if (k >= n) {
                out.printLine(0);
            } else {
                int kInt = (int) k;
                long sum = 0L;
                long sign = 1L;
                int l = n - kInt;

                for (int i = 0; i <= l; i++) {
                    long term = modPow(l - i, n, MOD);
                    term = (term * combination(l, l - i)) % MOD;
                    term = (term * sign) % MOD;
                    sum = (sum + term + MOD) % MOD;
                    sign = -sign;
                }

                long result = (2L * combination(n, kInt) % MOD) * sum % MOD;
                out.printLine(result);
            }
        }
        out.flush();
        out.close();
    }

    private static long combination(int n, int r) {
        if (r < 0 || r > n) return 0L;
        if (r == 0 || r == n) return 1L;
        long denom = (factorial[r] * factorial[n - r]) % MOD;
        return (factorial[n] * modPow(denom, MOD - 2, MOD)) % MOD;
    }

    private static long modPow(long base, long exp, long mod) {
        long res = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    private static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    private static long solve(long x, long[] values) {
        int n = values.length;
        long quotient = x / n;
        int remainder = (int) (x % n);
        return values[n - 1] * quotient + values[remainder];
    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        private String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int readInt() {
            return Integer.parseInt(next());
        }

        public long readLong() {
            return Long.parseLong(next());
        }

        public double readDouble() {
            return Double.parseDouble(next());
        }

        public String readLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream stream) {
            writer = new PrintWriter(new BufferedOutputStream(stream));
        }

        public void printLine(long value) {
            writer.println(value);
        }

        public void printLine(int value) {
            writer.println(value);
        }

        public void flush() {
            writer.flush();
        }

        public void close() {
            writer.close();
        }
    }
}
